<?php
require __DIR__.'/layout_start.php';if(isset($_GET['excluir'])){$id=(int)$_GET['excluir'];try{db()->beginTransaction();db()->prepare('DELETE FROM tbl_CarrinhoItens WHERE ID_Produto=?')->execute([$id]);db()->prepare('DELETE FROM tbl_Produtos WHERE ID_Produto=?')->execute([$id]);db()->commit();flash('success','Produto excluído.');redirect('produtos.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage()?:'Não foi possível excluir o produto.');redirect('produtos.php');}}$products=db()->query("SELECT p.*,m.NomeMarca,c.NomeCategoria,(SELECT UrlImagem FROM tbl_ProdutoImagem pi WHERE pi.ID_Produto=p.ID_Produto ORDER BY Principal DESC,ID_Imagem ASC LIMIT 1) UrlImagem FROM tbl_Produtos p JOIN tbl_Marca m ON m.ID_Marca=p.ID_Marca JOIN tbl_Categoria c ON c.ID_Categoria=p.ID_Categoria ORDER BY p.DataCadastro DESC")->fetchAll(); ?>
<div class="admin-head"><div><div class="eyebrow">CATÁLOGO</div><h1>Produtos.</h1></div><a class="btn btn-primary" href="produto_form.php">+ Novo produto</a></div><?php if($products): ?><table class="data-table"><tr><th>Produto</th><th>Marca / Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th></th></tr><?php foreach($products as $p): $status=normalize_product_status((int)($p['QtdEstoque']??0),(string)($p['StatusProduto']??'')); ?><tr><td style="display:flex;align-items:center;gap:10px"><img src="<?= e(product_image($p)) ?>" alt=""><span><?= e($p['Nome_Prod']) ?></span></td><td><?= e($p['NomeMarca']) ?><br><small><?= e($p['NomeCategoria']) ?></small></td><td><?= money((float)($p['ValorPromocional']?:$p['Valor_Preco'])) ?></td><td><?= $p['QtdEstoque'] ?></td><td><?= e($status) ?></td><td class="actions"><a class="action-edit" href="produto_form.php?id=<?= $p['ID_Produto'] ?>">Editar</a><a class="action-delete" data-confirm="Excluir este produto? Esta ação não pode ser desfeita." href="produtos.php?excluir=<?= $p['ID_Produto'] ?>">Excluir</a></td></tr><?php endforeach; ?></table><?php else: ?><div class="empty"><h3>O catálogo está vazio.</h3><a class="btn btn-primary" href="produto_form.php">Cadastrar primeiro produto</a></div><?php endif; ?><?php require __DIR__.'/layout_end.php'; ?>
